import{_ as r,a,b as t,c as i,d as n}from"./chunks/profile-edit.DyxMdkEa.js";import{_ as o,o as s,c as d,a3 as l}from"./chunks/framework.BlfGB29P.js";const k=JSON.parse('{"title":"3D Printer Card","description":"Compact Home Assistant card for Klipper and Moonraker with profiles, camera and temperature charts.","frontmatter":{"title":"3D Printer Card","description":"Compact Home Assistant card for Klipper and Moonraker with profiles, camera and temperature charts."},"headers":[],"relativePath":"en/projects/3d-printer-card/index.md","filePath":"en/projects/3d-printer-card/index.md","lastUpdated":1795870063000}'),p={name:"en/projects/3d-printer-card/index.md"};function c(h,e,m,f,u,g){return s(),d("div",null,[...e[0]||(e[0]=[l('<h1 id="_3d-printer-card" tabindex="-1">3D Printer Card <a class="header-anchor" href="#_3d-printer-card" aria-label="Permalink to &quot;3D Printer Card&quot;">​</a></h1><p><a href="/projects/3d-printer-card/">Deutsch</a> · <a href="/fr/projects/3d-printer-card/">Français</a></p><p><strong>Version 0.1.7. Works only with Klipper and Moonraker.</strong> Install and configure the <a href="https://github.com/marcolivierarsenault/moonraker-home-assistant" target="_blank" rel="noreferrer">Moonraker integration</a> for each printer. The card uses its HA entities without a separate login or printer connection.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p><a href="https://my.home-assistant.io/redirect/hacs_repository/?owner=rockbaer2007&amp;repository=3d-printer-card&amp;category=plugin" target="_blank" rel="noreferrer"><img src="'+r+'" alt="Open in Marketplace"></a></p><ol><li>Back up settings. Install and configure the <a href="https://my.home-assistant.io/redirect/hacs_repository/?owner=marcolivierarsenault&amp;repository=moonraker-home-assistant&amp;category=integration" target="_blank" rel="noreferrer">Moonraker integration in Marketplace</a>.</li><li>Add <code>https://github.com/rockbaer2007/3d-printer-card</code> as a custom <strong>Dashboard</strong> repository in Marketplace and download it. Not yet listed in the default Marketplace catalog.</li><li>Check <code>/hacsfiles/3d-printer-card/3d-printer-card.js</code> is registered as a <strong>JavaScript module</strong>, then reload the browser. Replace an existing local resource instead of loading both versions.</li><li>Add <strong>3D Printer Card</strong> to a dashboard. Its technical type remains <code>custom:moonraker-display-card</code>.</li></ol><p>Manual installation: copy the release JS file to <code>/config/www/3d-printer-card/</code> and register <code>/local/3d-printer-card/3d-printer-card.js?v=0.1.7</code> as a JavaScript module. No HA restart needed. Replace all example entities with your own.</p><h2 id="display-and-profiles" tabindex="-1">Display and profiles <a class="header-anchor" href="#display-and-profiles" aria-label="Permalink to &quot;Display and profiles&quot;">​</a></h2><ul><li>State, filename, progress, elapsed/remaining/projected time, ETA and layers, plus speed, fan and messages.</li><li>Nozzle/bed actual and target temperatures in one chart; board/pad actual temperatures in another. History requires those entities in HA Recorder.</li><li>Live camera on the right at approximately one third of the width, with an optional thumbnail. Narrow displays stack the content.</li><li>Compact fields, shallow charts, 24-column default and automatic height. Use a sections view; panel views force full width.</li><li>Up to 20 printer profiles with independent entities and cameras.</li></ul><p>Open <strong>Profil hinzufügen</strong> (add profile) or <strong>Profil bearbeiten</strong> (edit profile). Select the printer&#39;s <code>current_print_state</code> sensor under <strong>Drucker erkennen</strong> to detect its prefix. Choose cameras and adjust mappings using native HA selectors. Click <strong>Profil übernehmen</strong>, then <strong>Speichern</strong> in the outer editor. Editor labels are currently German; documentation is DE/EN/FR. Existing profiles remain compatible.</p><h2 id="screenshots-in-use" tabindex="-1">Screenshots in use <a class="header-anchor" href="#screenshots-in-use" aria-label="Permalink to &quot;Screenshots in use&quot;">​</a></h2><p>These screenshots show the card and its German-language editor. Click an image to open it at full size.</p><h3 id="overview-with-camera-and-temperature-charts" tabindex="-1">Overview with camera and temperature charts <a class="header-anchor" href="#overview-with-camera-and-temperature-charts" aria-label="Permalink to &quot;Overview with camera and temperature charts&quot;">​</a></h3><p><a href="/images/3d-printer-card/card-overview.png"><img src="'+a+'" alt="3D Printer Card for the Ender3 V2: status, progress, timing, camera on the right and nozzle, bed and system temperature charts"></a></p><h3 id="card-editor-with-profile-selection-and-preview" tabindex="-1">Card editor with profile selection and preview <a class="header-anchor" href="#card-editor-with-profile-selection-and-preview" aria-label="Permalink to &quot;Card editor with profile selection and preview&quot;">​</a></h3><p><a href="/images/3d-printer-card/card-editor.jpeg"><img src="'+t+'" alt="Visual card editor with printer profile selection, add and edit profile buttons, and the preview on the right"></a></p><h3 id="add-a-printer-profile" tabindex="-1">Add a printer profile <a class="header-anchor" href="#add-a-printer-profile" aria-label="Permalink to &quot;Add a printer profile&quot;">​</a></h3><p><a href="/images/3d-printer-card/profile-add.png"><img src="'+i+'" alt="Add printer profile dialog with profile name, print-state entity, detected prefix, camera and model thumbnail"></a></p><h3 id="edit-a-printer-profile" tabindex="-1">Edit a printer profile <a class="header-anchor" href="#edit-a-printer-profile" aria-label="Permalink to &quot;Edit a printer profile&quot;">​</a></h3><p><a href="/images/3d-printer-card/profile-edit.png"><img src="'+n+'" alt="Ender3 V2 profile editor with HA entity selection, camera, model thumbnail and expandable status, temperature and print-time mappings"></a></p><h2 id="cancellation-and-verification" tabindex="-1">Cancellation and verification <a class="header-anchor" href="#cancellation-and-verification" aria-label="Permalink to &quot;Cancellation and verification&quot;">​</a></h2><p>Read-only except for <strong>Cancel print</strong>, using the existing HA button for an active/paused print and a ready printer. Confirmation and a fresh state check are required. Profile changes send no commands. No filament consumption or lifetime statistics.</p><p>Verified with real entities on HA 2026.11.3: display, camera, charts and profile editing while preserving settings. Also 16 automated tests and browser tests at 390, 800 and 1500 pixels with no overflow or unwanted service calls. No real running print was cancelled during testing.</p><h2 id="downloads" tabindex="-1">Downloads <a class="header-anchor" href="#downloads" aria-label="Permalink to &quot;Downloads&quot;">​</a></h2><p>Ready-to-copy forum posts: <a href="https://github.com/rockbaer2007/3d-printer-card/blob/main/forum/forenbeitrag-de.md" target="_blank" rel="noreferrer">Deutsch</a> · <a href="https://github.com/rockbaer2007/3d-printer-card/blob/main/forum/forum-post-en.md" target="_blank" rel="noreferrer">English</a>.</p><ul><li><a href="https://github.com/rockbaer2007/3d-printer-card" target="_blank" rel="noreferrer">GitHub and full guide</a></li><li><a href="https://github.com/rockbaer2007/3d-printer-card/releases/tag/v0.1.7" target="_blank" rel="noreferrer">Release 0.1.7 with ZIP and JavaScript</a></li><li><a href="https://github.com/rockbaer2007/3d-printer-card/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">Changelog</a></li></ul><p>MIT license. Independent frontend project, separate from the Moonraker integration.</p>',27)])])}const _=o(p,[["render",c]]);export{k as __pageData,_ as default};
